const q=$('Owner context').first().json.query||{};
const matched=$('Read owner run').all().map(i=>i.json).filter(r=>r.run_id===q.id);
// A repeated send can record one run twice (same run id and client id): keep the most recently updated row. Different clients stay ambiguous.
const latest=new Map();for(const r of matched){const k=String(r.client_run_id||''),o=latest.get(k),at=String(r.updatedAt||''),oat=String(o?.updatedAt||'');if(!o||at>oat||(at===oat&&Number(r.id)>Number(o.id)))latest.set(k,r);}
const rows=[...latest.values()];
const safe=(v,n=800)=>typeof v==='string'?v.replace(/https?:\/\/\S+/gi,'[link omitted]').replace(/(?:token|authorization|secret|password|resume_url)\s*[:=]\s*[^\s,;]+/gi,'[hidden]').slice(0,n):'';
const arr=v=>Array.isArray(v)?v:[];
const parse=(s,f)=>{try{return JSON.parse(s)??f}catch{return f}};
if(rows.length!==1)return [{json:{http_status:rows.length?409:404,error:rows.length?'ambiguous_run':'not_found'}}];
const r=rows[0], gate=r.status==='awaiting_go_1'?'go1':r.status==='awaiting_go_2'?'go2':null;
const kind=gate==='go1'?'go1_ticket':'go2_ticket';
const events=$input.all().map(i=>i.json).filter(e=>e.run_id===r.run_id&&e.kind===kind&&e.contract_stamp===r.contract_stamp).sort((a,b)=>String(b.at).localeCompare(String(a.at)));
const ticket=parse(events[0]?.payload,null), round=Number(gate==='go1'?r.go1_rounds:r.go2_round);
const review=parse(r.review,{}), cost=parse(r.cost_estimate,{});
const candidate=gate==='go2'?ticket?.candidate:null;
function drive(v){
 if(typeof v!=='string')return null;
 const match=v.match(/^https:\/\/drive\.google\.com\/file\/d\/([A-Za-z0-9_-]+)\/view(?:\?usp=(?:drivesdk|sharing|drive_link))?$/);
 return match?'https://drive.google.com/file/d/'+match[1]+'/view':null;
}
const crypto=require('crypto');
const revision=crypto.createHash('sha256').update(JSON.stringify([r.run_id,r.status,round,r.contract_stamp,events[0]?.at||'',ticket])).digest('hex');
let allowed=gate==='go1'?['go','change','stop']:gate==='go2'&&Array.isArray(review.go2_decisions)?review.go2_decisions.filter(x=>['approve','repair','stop','review_again','approve_unreviewed'].includes(x)):[];
if(!ticket||!r.resume_url||!(gate==='go1'?r.go1_token:r.go2_token)||!Number.isSafeInteger(round)||round<0)allowed=[];
if(gate==='go1'&&(round>=3||!(ticket?.shots||[]).some(s=>s.kind!=='white')))allowed=allowed.filter(x=>x!=='change');
// Edit phase 2.4: an edit of an approved image is planned from that image (brief.edit.base); a plan change at its Go 1 holds the run, so it is not offered.
const briefEvent=$input.all().map(i=>i.json).find(e=>e.run_id===r.run_id&&e.kind==='brief');
if(gate==='go1'&&parse(briefEvent?.payload,null)?.edit?.base)allowed=allowed.filter(x=>x!=='change');
if(gate==='go2'&&round>=3)allowed=allowed.filter(x=>x!=='repair');
if(gate==='go2'&&!drive(candidate?.link))allowed=allowed.filter(x=>x==='stop');
// A ticket older than 24 hours cannot continue the run; stopping it stays possible, so the run is not left waiting with no way out.
const expired=Boolean(gate)&&(!events[0]?.at||Date.now()-Date.parse(events[0].at)>24*60*60*1000);
if(expired)allowed=allowed.filter(x=>x==='stop');
const ticketWarnings=arr(ticket?.warnings).concat(arr(ticket?.risks),arr(ticket?.not_confirmed).map(x=>'Not confirmed: '+safe(x)),arr(ticket?.stage04_precheck?.will_hold).map(x=>'Generation hold: '+safe(x)));
const shots=arr(ticket?.shots).slice(0,10).map(shot=>{
 const plan=Object.fromEntries(['room_size','setting','light','camera','presentation','person','rationale'].map(k=>[k,safe(shot.plan?.[k],1200)]));
 plan.room=Object.entries(shot.plan?.room||{}).filter(([k])=>['walls','floor','windows','zone'].includes(k)).map(([k,v])=>k+': '+safe(v,160)).join('; ');
 plan.midas_pieces=arr(shot.plan?.midas_pieces).slice(0,6).map(m=>safe(m.sku,40)+' · quantity '+(Number.isSafeInteger(m.count)?m.count:'not confirmed')+' · '+safe(m.purpose,160)+' · '+safe(m.rests_on,120)).join('; ');
 return {number:shot.n,output:safe(shot.output_id,80),kind:safe(shot.kind,40),frame:safe(shot.frame,120),check:safe(shot.plan_check,120),plan};
});
const numericCost=Object.fromEntries(Object.entries(cost).filter(([k,v])=>/^[a-z_]+$/.test(k)&&typeof v==='number'&&Number.isFinite(v)&&v>=0));
// Delivered files of a finished package or scene set: private Drive file links only, labelled, deduplicated, at most 30.
const deliveries=[],seen=new Set();
function collect(v,kind,label,depth){
 if(!v||typeof v!=='object'||depth>6||deliveries.length>=30)return;
 if(Array.isArray(v)){for(const x of v)collect(x,kind,label,depth+1);return;}
 const link=drive(v.link);
 if(link&&!seen.has(link)){seen.add(link);deliveries.push({link,label:safe(String(v.file_name||v.output_id||label),120),px:typeof v.px==='string'&&/^\d{2,5}x\d{2,5}$/.test(v.px)?v.px:null,kind});}
 for(const [k,x] of Object.entries(v))if(x&&typeof x==='object')collect(x,k==='master'?'master':k==='manifest'?'manifest':kind,label,depth+1);
}
collect(parse(r.package,null),'file','Package file',0);
collect(parse(r.scenes,null),'scene','Scene image',0);
return [{json:{http_status:200,runId:r.run_id,clientId:r.client_run_id,status:r.status,gate,round,revision,allowed,decisionNeeded:expired?'This approval ticket is more than 24 hours old, so the run cannot continue from it. You can stop the run; to try again, save the version again and send a new job.':safe(ticket?.decision_needed,1800),shots,warnings:ticketWarnings.slice(0,30).map(x=>safe(x)),candidate:drive(candidate?.link),review:{result:safe(review.result,80),defects:(Array.isArray(review.defects)?review.defects:[]).slice(0,20).map(x=>safe(typeof x==='string'?x:JSON.stringify(x))),uncertain:(Array.isArray(review.unsure)?review.unsure:[]).slice(0,20).map(x=>safe(typeof x==='string'?x:JSON.stringify(x)))},cost:numericCost,deliveries,asOf:new Date().toISOString()}}];

const it=$input.first();let probe=it.json.body?.payload;try{if(typeof probe==='string')probe=JSON.parse(probe)}catch{probe=null}if(probe?.transportProbe===true){if(!/^owner-[a-f0-9-]{36}$/.test(probe.clientRunId||'')||Object.keys(it.binary||{}).length!==1)throw Error('invalid_transport_probe');try{const key=Object.keys(it.binary)[0];const data=await this.helpers.getBinaryDataBuffer(0,key);if(!data.length||data.length>3*1024*1024)throw Error('invalid_probe_size');return [{json:{http_status:200,transportProbe:true,valid:true,bytes:data.length,clientId:probe.clientRunId}}];}catch(error){return [{json:{http_status:409,transportProbe:true,valid:false,error:'probe_binary_unavailable',errorType:String(error.name||'Error').replace(/[^A-Za-z]/g,'').slice(0,40)}}];}}
// Owner submission: 1 to 12 files (photos, plus specification files). Every file keeps its saved name (role-<uuid>) so that
// "02 Ingest files" matches it to payload.references by name and reads its role; nothing is renamed or dropped.
const MAX_FILES=12,MAX_FILE=3*1024*1024,MAX_TOTAL=14*1024*1024;
const EXT={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'};
const SPEC={'text/plain':'txt','text/csv':'csv','application/json':'json','application/pdf':'pdf','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'xlsx'};
// Same role reading as "02 Ingest files" (roleOf), so the bridge refuses what A7 would not use.
function roleOf(label){const r=String(label||'').trim().toLowerCase();if(!r)return '';if(/room|space|target/.test(r))return 'room';if(/look|inspiration/.test(r))return 'look';if(/previous|result|generation/.test(r))return 'previous';if(/view|angle/.test(r))return 'other_view';if(/spec|sheet|excel|document/.test(r))return 'spec';if(/product|vendor/.test(r))return 'product';return 'other';}
const item=$input.first();let p=item.json.body?.payload;try{if(typeof p==='string')p=JSON.parse(p)}catch{p=null}
const b=item.binary||{},keys=Object.keys(b);
if(!p||typeof p!=='object'||!/^owner-[a-f0-9-]{36}$/.test(p.clientRunId||'')||keys.length<1||keys.length>MAX_FILES)throw new Error('Invalid owner submission');
const refs=Array.isArray(p.references)?p.references:[];
if(refs.length!==keys.length)throw Error('owner_references_mismatch');
const NAME=/^(product|room|other_view|look|previous|spec)-[a-f0-9-]{36}$/,used=new Set(),out={},uploadFields=[];let total=0,products=0,rooms=0;
for(let i=0;i<keys.length;i++){
 const key=keys[i],f=b[key]||{},raw=String(f.fileName||''),bare=raw.replace(/\.(jpe?g|png|webp|txt|csv|json|pdf|xlsx)$/i,'');
 const idx=refs.findIndex((r,j)=>!used.has(j)&&r&&typeof r.name==='string'&&(r.name===raw||r.name===bare));
 if(idx===-1)throw Error('owner_file_without_reference');
 used.add(idx);
 const name=refs[idx].name,role=roleOf(refs[idx].role);
 if(!NAME.test(name)||!['product','room','other_view','look','previous','spec'].includes(role)||!name.startsWith(role+'-'))throw Error('invalid_owner_role');
 if(role==='product')products++;if(role==='room')rooms++;
 const mime=f.mimeType,ext=EXT[mime]||(role==='spec'?SPEC[mime]:undefined);if(!ext)throw Error('invalid_owner_image');
 const bytes=await this.helpers.getBinaryDataBuffer(0,key);
 if(!bytes.length||bytes.length>MAX_FILE)throw Error('invalid_owner_image');
 total+=bytes.length;if(total>MAX_TOTAL)throw Error('owner_upload_too_large');
 const field='files'+i;out[field]={data:bytes.toString('base64'),mimeType:mime,fileName:name,fileExtension:ext};uploadFields.push(field);
}
// A7 reads one product photo and at most one room photo; a second of either would be registered but never used.
if(products!==1||rooms>1)throw Error('owner_roles_invalid');
return [{json:{payload:JSON.stringify(p),uploadFields,fileCount:uploadFields.length,totalBytes:total},binary:out}];

function actionReceipt(response,expectedClientId){
 const r=response||{};let b=r.body??r.data;
 try{if(typeof b==='string')b=JSON.parse(b);}catch{b=null;}
 const json=b&&typeof b==='object'&&!Array.isArray(b);
 const httpOk=r.statusCode>=200&&r.statusCode<300&&!r.error;
 const intake=json&&b.ok===true&&b.status==='received'&&b.job_id===expectedClientId;
 const decision=json&&b.forwarded===true&&b.id===expectedClientId;
 const accepted=Boolean(httpOk&&(intake||decision));
 const error=!accepted&&json&&/^[a-z_]{1,80}$/.test(b.error||'')?b.error:
  !accepted&&r.statusCode>=500?'upstream_workflow_failed':null;
 // Return an application receipt even for a failed upstream request. An edge
 // gateway can replace HTTP 502 bodies; callers must check accepted explicitly.
 // A7's intake refuses a job it cannot start with its own client-safe reasons (problems); pass them on, short and plain,
 // so the owner sees why. Nothing else of the answer is passed.
 const problems=!accepted&&json&&Array.isArray(b.problems)?b.problems.filter(p=>typeof p==='string'&&p.trim()).slice(0,10).map(p=>p.trim().slice(0,300)):[];
 return {http_status:200,accepted,error,problems,forwarded:accepted&&decision,
  runId:accepted&&/^claude-a7-[A-Za-z0-9-]+$/.test(b.run_id||'')?b.run_id:null,
  clientId:accepted?expectedClientId:null,
  upstreamStatus:Number.isInteger(r.statusCode)?r.statusCode:null,
  receiptKind:accepted?'accepted':json?'rejected':r.error?'transport_error':'invalid_response',
  outcome:accepted?'received':'outcome_unknown',
  message:accepted?'A7 received the request. Refresh the queue to see the recorded result.':'A7 did not confirm receipt. Do not send a new request; check the queue first.'};
}
let expected;try{expected=JSON.parse($('Normalize owner upload').first().json.payload).clientRunId;}catch{try{expected=$('Validate owner decision').first().json.answer.id;}catch{}}return [{json:actionReceipt($input.first().json,expected)}];

// Edit phase 2.1 (19 Oct 2026): the scene images the owner approved in this run, with the Google Drive file id and checksum A7
// recorded at approval, so the owner site can start an edit from one exact image. Nothing else of the run record is added.
// 20 Oct 2026: also the white master of a finished white package (the owner's go 2 release of exactly that file), so a new job can
// make its scenes from it.
const out=$input.first().json;
if(out.http_status!==200)return [{json:out}];
const rows=$('Read owner run').all().map(i=>i.json).filter(x=>x.run_id===out.runId&&x.client_run_id===out.clientId).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))||Number(b.id)-Number(a.id));
let done=null;try{done=JSON.parse(rows[0]?.scenes||'null')?.done;}catch(e){done=null;}
let pkg=null;try{pkg=JSON.parse(rows[0]?.package||'null');}catch(e){pkg=null;}
const results=[];
const m=pkg&&pkg.master,rel=pkg&&pkg.release;
if(pkg&&pkg.outcome==='white_package_ready'&&m&&rel&&rel.run_id===out.runId&&rel.output_id==='white_master'&&['reviewed_owner_approved','owner_exception'].includes(rel.classification)&&/^[A-Za-z0-9_-]{10,200}$/.test(String(m.drive_file_id||''))&&/^[a-f0-9]{64}$/.test(String(m.sha256||''))&&rel.candidate_sha256===m.sha256)
 results.push({outputId:'white_master',kind:'white',driveFileId:m.drive_file_id,sha256:m.sha256,px:typeof m.px==='string'&&/^\d{2,5}x\d{2,5}$/.test(m.px)?m.px:null,fileName:String(m.file_name||'white_master').replace(/https?:\/\/\S+/gi,'').slice(0,160),reviewed:rel.classification==='reviewed_owner_approved',approvedAt:typeof rel.at==='string'?rel.at:null});
if(done&&typeof done==='object'&&!Array.isArray(done))for(const [outputId,d] of Object.entries(done)){
 const c=d&&d.candidate;
 if(results.length>=30||!d||d.by!=='owner'||!c||!/^[a-z0-9_]{1,60}$/.test(outputId)||!/^[A-Za-z0-9_-]{10,200}$/.test(String(c.drive_file_id||''))||!/^[a-f0-9]{64}$/.test(String(c.sha256||'')))continue;
 results.push({outputId,kind:'scene',driveFileId:c.drive_file_id,sha256:c.sha256,px:typeof c.px==='string'&&/^\d{2,5}x\d{2,5}$/.test(c.px)?c.px:null,fileName:String(c.file_name||outputId).replace(/https?:\/\/\S+/gi,'').slice(0,160),reviewed:!d.without_review,approvedAt:typeof d.at==='string'?d.at:null});
}
return [{json:{...out,results}}];
